const WEAPON_FIXES=[["Abysseram","In FLYING WATERS, use CORAL CAVE Flag, follow the route to the optional handhold CLIMBING WALL and defeat the BOURGEON just beyond that wall. The drop is Gustave/Verso's Abysseram.",["act1","Collectibles · Flying Waters · Coral Cave / Lumieran Streets"],[]],["Cruleram","In FLYING WATERS from NOCO'S HUT Flag return to the chamber with the HUGE ANCHOR. Defeat the enemy group roaming beside the anchor to get Cruleram.",["act1","Collectibles · Flying Waters · Coral Cave / Lumieran Streets"],[]],["Troubadim","At FLYING WATERS LUMIÈRAN STREETS Flag find the LEFT wall HANDHOLDS, climb and grapple to the CHROMATIC TROUBADOUR. Beat it for Troubadim.",["act1","Collectibles · Flying Waters · Coral Cave / Lumieran Streets"],[]],["Brulerum","At FLYING WATERS NOCO'S HUT Flag head toward the LARGE ANCHOR and fight the nearby BRÛLEUR enemy group; it drops Brulerum.",["act1","Collectibles · Flying Waters · Coral Cave / Lumieran Streets"],[]],["Sakaram","In ANCIENT SANCTUARY start from ENTRANCE Flag, take the main path to the first ROBUST SAKAPATATE encounter and defeat it for Sakaram.",null,[]],["Trebuchim","From ANCIENT SANCTUARY SANCTUARY MAZE Flag take the route to the CATAPULT SAKAPATATE in the lower clearing and defeat it for Lune's Trebuchim.",null,[]],["Medalum","In GESTRAL VILLAGE visit CHIEF GOLGRA'S HOUSE to unlock registration, then join the ARENA tournament. Choose MAELLE for the FOURTH and FINAL solo fight against THE STRANGER (Sciel); winning with Maelle awards Medalum.",null,[]],["Hevason","After Gestral Village's tournament, return to CHIEF GOLGRA in her house and accept her optional duels. Win ALL FOUR of Golgra's fights to receive Hevason; these are very difficult if attempted immediately.",null,[]],["Plenum","In YELLOW HARVEST follow the path from YELLOW SPIRE WRECKS Flag to the GLAISE boss guarding the upper ridge. Defeat Glaise for Plenum.",["act1","Collectibles · Yellow Harvest / Lost Woods"],["rough"]],["Jarum","Use Esquie's SWIMMING in Act 2 to reach the island DIRECTLY SOUTH of WHITE TREE. Find and defeat its CHROMATIC JAR boss to receive Jarum.",null,["swim"]],["Glaceso","On the Continent exit MONOCO'S STATION and head NORTHWEST along the snowy path to the roaming Nevron GROUP. Defeat that group for Glaceso.",null,["swim"]],["Seeram","With Esquie's swimming and coral traversal, reach COASTAL CAVE. Find the CRULER merchant beside a FIREPLACE in the cave, duel him if needed and buy Seeram for 21,275 Chroma.",["act2","Collectibles · Coastal Cave"],["swim","reef"]],["Lighterim","During ACT 1 SPRING MEADOWS, after joining Lune, proceed into ABANDONED EXPEDITIONER CAMP and defeat the enemy GROUP along the path leading toward INDIGO TREE. Lighterim can drop there; there is a later merchant backup in Coastal Cave.",["act1","Spring Meadows · Abandoned Camp → Indigo Tree"],[]],["Gobluson","Enter COASTAL CAVE during the later Act 2 coast sweep and locate the CRULER Gestral merchant beside its FIREPLACE. Buy Sciel's Gobluson for 19,240 Chroma.",["act2","Collectibles · Coastal Cave"],["swim","reef"]],["Danseso","In OLD LUMIÈRE, take the side ROPE DOWN from the main route to the CHROMATIC DANSEUSE boss. Defeat her to receive Verso's Danseso.",["act2","Collectibles · Old Lumière"],["swim"]],["Battlum","In OLD LUMIÈRE fast-travel to RIGHT STREET Flag and fight the CHEVALIÈRE enemy GROUP on the main road. Collect Maelle's Battlum from the encounter.",["act2","Collectibles · Old Lumière"],["swim"]],["Melarum","Complete OLD LUMIÈRE through MANOR GARDENS and beat the main RENOIR boss fight. His victory rewards contain Melarum.",["act2","Collectibles · Old Lumière"],["swim"]],["Nusaro","From OLD LUMIÈRE RIGHT STREET Flag head into the LEFT-hand branch of the ruined street and continue to its DEAD END. Pick up Monoco's Nusaro lying there.",["act2","Collectibles · Old Lumière"],["swim"]],["Scaverim","In FALLING LEAVES from RESINVEIL GROVE Flag find the LOCKED GATE and solve the area path to reach the boss behind it. Defeat the SCAVENGER to receive Lune's Scaverim.",["act2","Collectibles · Falling Leaves"],["swim","reef"]],["Blizzon","At FALLING LEAVES RESINVEIL GROVE Flag follow the boss detour toward CHROMATIC BALLET, defeat the chromatic encounter and claim Blizzon.",["act2","Collectibles · Falling Leaves"],["swim","reef"]],["Direton","From FALLING LEAVES RESINVEIL GROVE Flag use the GRAPPLE across the merchant detour, defeat the Gestral merchant if necessary and buy Direton for 30,125 Chroma.",["act2","Collectibles · Falling Leaves"],["swim","reef"]],["Confuso","In VISAGES take JOY VALE from PLAZA Flag and activate its giant MOUTH. After opening the path, defeat the guardian enemy beside it to receive Confuso.",["act2","Collectibles · Visages"],["swim"]],["Contorso","In VISAGES take the ANGER VALE branch, activate the giant MOUTH, then turn RIGHT at the junction and defeat the enemy blocking the optional passage for Contorso.",["act2","Collectibles · Visages"],["swim"]],["Chapelim","In VISAGES clear the PATH OF JOY and defeat its FINAL BOSS, the Jovial Moissonneuse; Lune's Chapelim is its reward.",["act2","Collectibles · Visages"],["swim"]],["Clierum","In VISAGES finish ANGER VALE and defeat its FINAL BOSS to earn Maelle's Clierum.",["act2","Collectibles · Visages"],["swim"]],["Moisson","After the Act 2 sea routes open, swim to the RED ISLAND SOUTHWEST of VISAGES, then reach its outer rim. Defeat the CHROMATIC MOISSONNEUSE roaming on the edge for Sciel's Moisson.",["act2","Continent · western expansion"],["swim","reef"]],["Sadon","At VISAGES PLAZA Flag speak to the hub's Gestral merchant and win his duel to unlock Sadon; buy it for 12,400 Chroma.",["act2","Collectibles · Visages"],["swim"]],["Boucharo","In VISAGES finish the SADNESS VALE story branch and defeat its FINAL BOSS. Boucharo is the Monoco weapon rewarded at the end.",["act2","Collectibles · Visages"],["swim"]],["Sireso","In SIRÈNE use DANCING CLASSES Flag, then progress to the PAINT CAGE and ride the ELEVATOR just beyond it to collect Sireso.",["act2","Sirène"],["swim","reef"]],["Colim","During SIRÈNE's interior ribbons and chamber route, locate the CHORALE enemy groups and defeat any CHORALE in battle. It drops Lune's Colim.",["act2","Sirène"],["swim","reef"]],["Saperim","After Esquie learns to break CORAL REEFS, reach the FAR EASTERN BEACH of SIRÈNE's island on the Continent and defeat the enemy group including a SAPLING. The group drops Lune's Saperim.",["act2","Collectibles · Continent · eastern detour","Continent · eastern detour"],["swim","reef"]],["Chantenum","From SIRÈNE's CRUMBLING PATH Flag climb the HANDHOLDS to the Gestral merchant, win the duel and buy Maelle's Chantenum for 18,645 Chroma.",["act2","Sirène"],["swim","reef"]],["Tissenum","Within SIRÈNE reach the TISSEUR optional boss and defeat it; Tissenum is the Maelle weapon that drops from Tisseur.",["act2","Sirène"],["swim","reef"]],["Tisseron","Finish SIRÈNE's main story route and defeat the SIRÈNE AXON. Sciel's Tisseron drops from the encounter.",["act2","Sirène"],["swim","reef"]],["Dreameso","Within the MONOLITH's TAINTED LUMIÈRE section locate the LARGE TREE, take the adjacent GRAPPLE and collect Dreameso on the ledge beyond.",["act2","The Monolith"],["swim"]],["Braselim","Inside the MONOLITH's TAINTED HEARTS section follow the main story path and defeat the roaming Nevron GROUP. It drops Lune's Braselim.",["act2","The Monolith"],["swim"]],["Lithelim","In MONOLITH's TAINTED LUMIÈRE segment pass the GRAPPLE from the ruined street and defeat the enemy group beyond it. It drops Lithelim.",["act2","The Monolith"],["swim"]],["Veremum","In MONOLITH's TAINTED MEADOWS section pass the SECOND story cutscene, talk to the nearby merchant and purchase Veremum for 27,744 Chroma.",["act2","The Monolith"],["swim"]],["Garganon","During MONOLITH's TAINTED HEARTS level climb the HANDHOLDS to the merchant landing and buy Monoco's Garganon for 26,384 Chroma after unlocking stock.",["act2","The Monolith"],["swim"]],["Fragaro","At MONOLITH TAINTED MEADOWS just AFTER the second cutscene find the Gestral merchant and buy Monoco's Fragaro for 35,360 Chroma.",["act2","The Monolith"],["swim"]],["Bourgelon","After completing OLD LUMIÈRE, swim through reefs to COASTAL CAVE and find the CRULER merchant by the FIREPLACE. Buy Bourgelon for 17,760 Chroma; the Chromatic Bourgeon in the Monolith is a later alternate source.",["act2","Collectibles · Coastal Cave"],["swim","reef"]],["Chevalam","After unlocking FLIGHT, reach the CRIMSON FOREST dungeon and fast-travel to THE THREE BLADES Flag. Defeat the FINAL BOSS here to acquire Verso's Chevalam.",["act3","Collectibles · Act 3 · relationships and full traversal"],["fly"]],["Corpeso","After Old Lumière grants coral-breaking swim, reach DARK SHORES and enter BLOODIED BEACH Flag. Follow the beach to the CRASHED SHIP and defeat the enemies grouped around its hull to obtain Corpeso.",["act2","Continent · western expansion"],["swim","reef"]],["Barrier Breaker","AFTER defeating BOTH Act 2 Axons, return automatically to CAMP and speak with the CURATOR by his cave. He forges and hands Maelle the BARRIER BREAKER weapon before you can break the barrier to the Monolith.",["act2","Return from second Axon","Sirène"],["swim"]],["Chalium","After the Old Lumière sea-reef upgrade, sail to SINISTER CAVE and follow its path to the FINAL BOSS. Defeat the boss to receive Maelle's Chalium; flight is not required.",["act2","Continent · western expansion"],["swim","reef"]],["Corderon","After Old Lumière gives reef traversal, enter SINISTER CAVE. Circle the inner caverns back toward the CENTRAL CHAMBER containing the DEAD MERCHANT and collect Sciel's Corderon lying by the body.",["act2","Continent · western expansion"],["swim","reef"]],["Blodam","After Old Lumière grants CORAL BREAKING, swim to the eastern Continent island beyond SERPENPHARE's waters that also contains EXPEDITION 43. Defeat the CHROMATIC REAPER CULTIST roaming in the open and obtain Blodam.",["act2","Collectibles · Continent · eastern detour","Continent · eastern detour"],["swim","reef"]],["Tireso","With FLIGHT unlocked enter THE REACHER and reach FOGGY AREA Flag, then take the path past the HOT-AIR BALLOON to the Gestral merchant. Defeat him and purchase Tireso for 51,635 Chroma.",["act3","Collectibles · Act 3 · relationships and full traversal"],["fly"]],["Kralim","In YELLOW HARVEST use YELLOW SPIRE WRECKS Flag, exit the cave and hug the RIGHT wall to a pit. DROP into the cavern below and defeat the three CHROMATIC ORPHELINS to collect Lune's Kralim; these optional enemies are unusually strong.",["act1","Collectibles · Yellow Harvest / Lost Woods"],["rough"]],["Lithum","Within THE REACHER progress to ALICIA's boss encounter and defeat her. Maelle's Lithum drops from this battle.",["act3","Collectibles · Act 3 · relationships and full traversal"],["fly"]],["Glaisum","After coral-breaking swim unlocks, reach FALLING LEAVES and use RESINVEIL GROVE Flag. Defeat the FIRST Nevron group just outside that flag to collect Maelle's Glaisum, rather than waiting for a flying-only late-game area.",["act2","Collectibles · Falling Leaves"],["swim","reef"]],["Choralim","With Esquie's flight reach SIRÈNE'S DRESS dungeon. Fight and defeat the CHROMATIC GLISSANDO here; it drops Lune's Choralim.",["act3","Collectibles · Act 3 · relationships and full traversal"],["fly"]],["Ballaro","On the Act 2 Continent after Old Lumière, travel the coastline NORTH of THE CROWS portal and defeat the enemy GROUP with BALLET, DÉMINEUR and GREATSWORD CULTIST. Collect Ballaro from the encounter; Chromatic Glissando at Sirène's Dress is a later source.",["act2","Continent · western expansion"],["swim","reef"]],["Guleson","With FLIGHT enter ENDLESS NIGHT SANCTUARY, fast-travel to NIGHT TOTEM Flag and buy Sciel's Guleson from the Gestral merchant for 80,040 Chroma.",["act3","Collectibles · Act 3 · relationships and full traversal"],["fly"]],["Facesum","Fly to ISLE OF THE EYES on the Continent, complete its dungeon and defeat the FINAL BOSS to receive Maelle's Facesum.",["act3","Collectibles · Act 3 · relationships and full traversal"],["fly"]],["Minason","In THE CROWS shoot the MAGIC BLACK CROWS around the area until CHROMATIC CHAPELIER appears. Defeat that boss to receive Sciel's Minason.",["act3","Collectibles · Act 3 · relationships and full traversal"],["fly"]],["Urnaro","Fly to SKY ISLAND and reach the CHROMATIC GLAISE optional boss. Defeat it to receive Monoco's Urnaro.",["act3","Collectibles · Act 3 · relationships and full traversal"],["fly"]],["Brumaro","In Act 3 fly to the isolated FLOATING ISLAND SOUTH OF THE FOUNTAIN. Defeat the CHROMATIC ABERRATION waiting on the island to obtain Monoco's Brumaro.",["act3","Continent · first flight sweep"],["fly"]],["Liteso","During the ACT 3 LUMIÈRE story visit use CENTRAL PLAZA Flag and defeat the enemy GROUP in the middle of the plaza. Collect Verso's Liteso from that encounter.",["act3","Story finale · Lumière"],["fly"]],["Volesterum","At ACT 3 LUMIÈRE's GARDENS entrance find the nearby Gestral merchant, win the duel and buy Maelle's Volesterum for 31,008 Chroma.",["act3","Story finale · Lumière"],["fly"]],["Litheson","At ACT 3 LUMIÈRE CENTRAL PLAZA Flag fight the enemy GROUP patrolling the CENTER of the plaza for Sciel's Litheson.",["act3","Story finale · Lumière"],["fly"]],["Gesam","Inside FLYING MANOR use CENTRAL PLAZA Flag and ride the ELEVATOR to the upper section; take the LEFT path at the top and collect Verso's Gesam.",["endgame","Collectibles · Flying Manor"],["fly"]],["Elerim","In Act 2 after reefs are broken, enter SINISTER CAVE and search beneath the LARGE STONE STATUE in its inner chamber for Elerim. You need not wait for Flying Manor's later merchant stock.",["act2","Continent · western expansion"],["swim","reef"]],["Snowim","In FROZEN HEARTS after recruiting Monoco, proceed to the FINAL BOSS GARGANT and defeat it. Lune's Snowim drops alongside the Eternal Ice needed for the station merchant.",["act2","Collectibles · Frozen Hearts"],["swim"]],["Seashellum","Within FLYING MANOR take the ELEVATOR up from CENTRAL PLAZA Flag to the Gestral merchant and buy Seashellum for 75,795 Chroma.",["endgame","Collectibles · Flying Manor"],["fly"]],["Martenon","Inside FLYING MANOR take the ELEVATOR from CENTRAL PLAZA Flag to the upper merchant and buy Sciel's Martenon for 97,800 Chroma.",["endgame","Collectibles · Flying Manor"],["fly"]],["Joyaro","After Esquie learns FLIGHT, enter ENDLESS NIGHT SANCTUARY and find its ULTIMATE SAKAPATATE optional boss. Defeat it to receive Monoco's Joyaro.",["act3","Collectibles · Act 3 · relationships and full traversal"],["fly"]],["Sidaro","In FLYING MANOR from CENTRAL PLAZA Flag take the ELEVATOR to the upper merchant and buy Monoco's Sidaro for 76,610 Chroma.",["endgame","Collectibles · Flying Manor"],["fly"]],["Nosaram","Only after Esquie can DIVE, enter RENOIR'S DRAFTS and from the ENTRANCE Flag take the GRAPPLE to the merchant landing. Purchase Verso's Nosaram for 107,475 Chroma.",["endgame","Optional regions, bosses and secret weapons"],["dive"]],["Simoso","After unlocking DIVING in Act 3, enter RENOIR'S DRAFTS and reach its ABYSS superboss section. Defeat SIMON, THE DIVERGENT STAR for Verso's Simoso.",["endgame","Optional regions, bosses and secret weapons"],["dive"]],["Painerim","Enter RENOIR'S DRAFTS after the Act 3 DIVE ability unlock. From ENTRANCE Flag use the GRAPPLE to reach the Gestral merchant and buy Painerim for 93,045 Chroma.",["endgame","Optional regions, bosses and secret weapons"],["dive"]],["Yeverum","In RENOIR'S DRAFTS after DIVING unlock, reach the Gestral merchant after the entrance GRAPPLE and buy Yeverum for 101,608 Chroma.",["endgame","Optional regions, bosses and secret weapons"],["dive"]],["Charnon","After DIVING unlocks, from RENOIR'S DRAFTS ENTRANCE Flag reach the Gestral merchant past the GRAPPLE and buy Sciel's Charnon for 89,884 Chroma.",["endgame","Optional regions, bosses and secret weapons"],["dive"]],["Chromaro","After unlocking DIVING, enter RENOIR'S DRAFTS and from ENTRANCE Flag follow the GRAPPLE side route to the merchant, then buy Chromaro for 102,585 Chroma.",["endgame","Optional regions, bosses and secret weapons"],["dive"]]];
for(const [name,directions,move,ability] of WEAPON_FIXES)apply(name,directions,{move,ability,source:W});

/* Complete 13 Thank You Update weapon checks. */
const DLC_WEAPONS=[["Esquim","In VERSO'S DRAFTS find PAINT CAGE 22 in the OPEN PLAYGROUND detour; shoot the THREE anomalies around the cage and take Lune's Esquim from its reward."],["Cannaro","Deep in VERSO'S DRAFTS track down the CHROMATIC MACHINAPIEDS optional enemy and defeat it for Monoco's Cannaro."],["Sucreso","Inside VERSO'S DRAFTS reach the large GINGERBREAD DOOR landmark and look HIGH ABOVE it for a TREEHOUSE. Climb up to the treehouse to collect Verso's Sucreso."],["Cleim","After unlocking the ENDLESS TOWER bonus encounter, defeat CLEA UNLEASHED and claim Lune's Cleim as the boss reward."],["Duollison","In the ENDLESS TOWER bonus fights defeat the DUOLLISTES duo; it drops Sciel's Duollison."],["Baguettaro","In VERSO'S DRAFTS, reach CANDY LAND Flag and locate its hidden MIME. Defeat the Mime to earn Monoco's Baguettaro weapon."],["Esquion","At VERSO'S DRAFTS CANDY LAND Flag start climbing the wall toward the MIME, but HALF-WAY along the HANDHOLD traverse turn into the SIDE PATH instead. Sciel's Esquion is on that branch."],["Esquiaro","At VERSO'S DRAFTS GESTRAL BATHS Flag locate the DIVING BOARD over the water. Hit the GESTRAL blocking the board to receive Monoco's Esquiaro."],["Esqium","In VERSO'S DRAFTS enter GESTRAL CAROUSEL and find the CHROMATIC FRANCTALE optional encounter in the carousel area. Defeat it to collect Maelle's Esqium."],["Bonbim","At VERSO'S DRAFTS RÊVERIE PATH Flag find its Gestral merchant, WIN THE MERCHANT DUEL and buy Lune's Bonbim for 102,424 Chroma."],["Licorum","From VERSO'S DRAFTS RÊVERIE PATH Flag go to the CHROMATIC LICORNE boss side path and beat that encounter to obtain Maelle's Licorum."],["Sucetton","In VERSO'S DRAFTS near RÊVERIE PATH Flag track the CHROMATIC BARBASUCETTE optional boss and defeat it to obtain Sciel's Sucetton."],["Esquiso","In VERSO'S DRAFTS reach the ROOT OF ALL EVIL and fight OSQUIO, the area's main optional boss. Defeat Osquio for Verso's Esquiso."]];
for(const [name,directions] of DLC_WEAPONS)apply(name,directions,{source:W,ability:[name==="Cleim"||name==="Duollison"?"fly":"dive"]});

/* First-available base-game outfit routes; do not treat a cosmetic as a generic catalog entry. */
const EARLY_OUTFITS=[["Gustave — Baguette outfit","In SPRING MEADOWS fast-travel to GRAND MEADOW Flag. Follow the LEFT cliffside detour and grapple over to the small hidden platform containing a MIME. Defeat the Mime to receive Gustave's Baguette outfit.",null,[]],["Gustave — Swimsuit outfit","On your first Continent visit after FLYING WATERS, travel west of ANCIENT SANCTUARY and enter the nearby GESTRAL BEACH. Complete the rotating logs/parkour course, then answer the Gestral's question with 17 to claim Gustave's Swimsuit.",null,[]],["Lune — Swimsuit 1 outfit","At the GESTRAL BEACH west of Ancient Sanctuary, finish the rotating-logs PARKOUR challenge. AFTER claiming Gustave's reward, speak to the same host Gestral again for Lune's Swimsuit I.",null,[]],["Lune — Baguette outfit","Enter ANCIENT SANCTUARY and travel to SANCTUARY MAZE Flag. Follow the RIGHT edge past the low crawlspace and ruined hut; locate the hidden MIME in the flowering clearing behind the hut, defeat it and claim Lune's Baguette outfit.",null,[]],["Gustave — Lumiere Suit outfit","On the Continent from GESTRAL VILLAGE'S entrance, travel EAST along the dirt route to the Gestral merchant near the rocky rise. Purchase Gustave's Lumière Suit for 1,000 Chroma while he is still available in Act 1.",null,[]],["Gustave — Pure outfit","In GESTRAL VILLAGE talk to KARATOM beside the unfinished Sakapatate machine and accept his Blue Mushroom quest. Enter ESQUIE'S NEST, collect the Blue Mushroom on its main cavern detour, then RETURN to Karatom and win his duel BEFORE ending Act 1 to get Gustave's Pure outfit.",["act1","Esquie's Nest → return to Village"],[]],["Gustave — Sakapatate outfit","In GESTRAL VILLAGE head from the BAZAAR toward KARATOM'S WORKSHOP and find Delsitra, the Gestral merchant beside the torch. Buy Gustave's Sakapatate outfit for 1,000 Chroma BEFORE the Stone Wave Cliffs finale.",null,[]],["Lune — Sakapatate outfit","In GESTRAL VILLAGE find ALEXSOUDRO at the BASE of the enormous STONE PILLAR, then climb its accessible rope/handhold route to PURUMI, the small blue-and-purple Gestral stranded on top. Talk to Purumi and convince him to come down, then return to his guardian for Lune's Sakapatate outfit.",null,[]],["Maelle — Lumiere outfit","From GESTRAL VILLAGE take the main Continent path EAST to the Gestral merchant beyond the village entrance and buy Maelle's Lumière outfit for 1,000 Chroma.",null,[]],["Maelle — Sakapatate outfit","From the GESTRAL VILLAGE ARENA Flag walk RIGHT past the two tall spectators, through the BROKEN ARCH to ONO-PUNCHO. Complete the challenge by dealing at least 9,999 damage to Ono-Puncho in a single hit; talk to him afterward for Maelle's Sakapatate outfit.",null,[]],["Sciel — Sakapatate outfit","Once Sciel joins after the GESTRAL VILLAGE tournament, head to the theatre plaza along the RIGHT side of the town. Locate ALEXCYCLO beside the performing area and buy Sciel's Sakapatate outfit for 1,000 Chroma.",null,[]],["Gustave — Chic outfit","After visiting FLYING WATERS on the first Continent landmass, approach the enormous carved stone-face entrance to ESQUIE'S NEST. Find the Gestral merchant CARRABI at the nearby coastal beach stall to its EAST and buy Gustave's Chic outfit for 2,000 Chroma before Act 1 ends.",null,[]],["Sciel — Baguette outfit","In ESQUIE'S NEST pass the ENTRANCE Flag and drop into the first large cavern. Take the optional side ledge before François' Cave and fight the hidden MIME; it awards Sciel's Baguette outfit.",null,[]],["Maelle — Skirt outfit","In STONE WAVE CLIFFS fast-travel to TIDE CAVERNS Flag, then use the nearby ZIPLINE and defeat the miniboss along the detour. Enter the MANOR DOOR beyond the fight; in the Manor inspect the WARDROBE to obtain Maelle's Skirt outfit.",null,[]],["Lune — Swimsuit 2 outfit","After Esquie learns to SWIM in Act 2, reach the GESTRAL BEACH RAFTING CLUB via the eastern sea route and challenge the STRONGEST Gestral at the volleyball arena. Return his serves to win the strongest match and claim Lune's Swimsuit II.",null,["swim"]],["Verso — Expedition outfit","During ACT 2 after recruiting Verso, set up CAMP on the Continent and choose CHECK UP ON THE OTHERS. Talk with Maelle and watch the camp cutscene that awards Verso's Expedition outfit; revisit the camp after story events if the scene has not yet appeared.",null,["swim"]],["Lune — Pure outfit","After recruiting MONOCO, visit MONOCO'S STATION Flag and locate the GRANDIS FASHIONIST wearing a bright RED BERET near the train tracks. Speak using Lune, Maelle or Sciel and complete his three-line poetry challenge for Lune's Pure outfit.",null,["swim"]],["Maelle — Pure outfit","At MONOCO'S STATION after Monoco joins, locate the red-beret GRANDIS FASHIONIST beside the train. Answer the poem with 'While shadows fade to silence, gone beyond our sight', 'Death untangles threads, revealing what's begun', then 'Eternity then cradles us, a promise to appease' to earn Maelle's Pure outfit.",null,["swim"]],["Sciel — Pure outfit","At MONOCO'S STATION after recruiting Monoco, talk to the RED-BERET GRANDIS FASHIONIST beside the train tracks with a female party member selected. Complete the three poetry responses correctly for Sciel's Pure outfit.",null,["swim"]],["Sciel — Skirt outfit","Exit MONOCO'S STATION onto the Continent and travel WEST toward the snowy forest. Locate the Gestral merchant CARNOVI just west of the station's entrance and buy Sciel's Skirt outfit for 5,000 Chroma.",null,["swim"]],["Lune — Danseuse outfit","Enter FROZEN HEARTS via the EAST exit of Monoco's Station, find the DANSEUSE who challenges you to a PARRY contest in the icy area, and correctly parry her sequence. Speak with her again to claim Lune's Danseuse outfit.",null,["swim"]],["Sciel — Danseuse outfit","In FROZEN HEARTS locate the hidden MIME in the icy cave side route and the Gestral merchant VEROGO standing nearby. Buy Sciel's Danseuse outfit from Verogo for 10,000 Chroma.",null,["swim"]],["Verso — Pelerin outfit","In FROZEN HEARTS follow the icy side passages to the MIME clearing and locate merchant VEROGO near the Mime. Purchase Verso's Pèlerin outfit from Verogo for 20,000 Chroma.",null,["swim"]],["Lune — Chic outfit","After OLD LUMIÈRE opens Esquie's coral-breaking traversal, sail to the CONTINENT shore NORTH of COASTAL CAVE's entrance and find the Gestral merchant beside that portal. Buy Lune's Chic outfit for 10,000 Chroma.",null,["swim","reef"]],["Maelle — Chic outfit","With reef-breaking swimming unlocked, swim to the CONTINENT beach NORTH of COASTAL CAVE and find the Gestral merchant standing along the coast. Buy Maelle's Chic outfit for 10,000 Chroma.",null,["swim","reef"]],["Sciel — Chic outfit","After OLD LUMIÈRE, sail to COASTAL CAVE's region and locate the merchant on the shoreline immediately NORTH of its portal. Buy Sciel's Chic outfit for 10,000 Chroma.",null,["swim","reef"]],["Verso — Chic outfit","Once Esquie can traverse coral reefs, sail to the BEACH NORTH of COASTAL CAVE and speak to the Gestral merchant outside its entrance. Purchase Verso's Chic outfit for 10,000 Chroma.",null,["swim","reef"]],["Monoco — Chic outfit","After unlocking Esquie's coral-breaking swim, approach COASTAL CAVE by sea and find the Gestral merchant on the COAST NORTH of the portal. Buy Monoco's Chic outfit for 10,000 Chroma.",null,["swim","reef"]],["Verso — Baguette outfit","In VISAGES travel from PLAZA Flag to the SIDE PASSAGE with the hidden MIME (look behind the cracked stone wall along the main route). Defeat the Mime to receive Verso's Baguette outfit.",null,["swim"]],["Verso — Simple outfit","After the OLD LUMIÈRE sea upgrade, swim to the SMALL ISLAND near VISAGES and find the Gestral merchant on its sandy landing. Purchase Verso's Simple outfit for 5,000 Chroma.",null,["swim","reef"]],["Lune — Sirene outfit","In SIRÈNE travel through the DANCING CLASSES Flag into the GLISSANDO boss section and defeat the GLISSANDO. Claim Lune's Sirène outfit from the encounter.",null,["swim","reef"]],["Sciel — Sirene outfit","With reef-breaking swimming after Old Lumière, beach Esquie on the EAST COAST of SIRÈNE's island and find the Gestral merchant PEARO. Buy Sciel's Sirène outfit for 5,000 Chroma.",null,["swim","reef"]],["Verso — Pure outfit","Swim to the SMALL ISLAND NORTHWEST of SIRÈNE on the Continent once the nearby sea channels are open. Find the Gestral merchant on the beach and purchase Verso's Pure outfit for 10,000 Chroma.",null,["swim","reef"]],["Gustave — Renoir's Suit outfit","Inside the MONOLITH ascend through its TAINTED zones to the mandatory RENOIR boss. Defeat Renoir; Gustave's Renoir's Suit is granted by the story fight, although Gustave may not be an active party member in this run.",null,["swim"]],["Verso — Renoir's Suit outfit","At the end of the MONOLITH's TAINTED story route, defeat RENOIR in the mandatory confrontation; check Verso's Outfit menu for Renoir's Suit from the rewards.",null,["swim"]]];
for(const [name,desc,move,ability] of EARLY_OUTFITS)apply(name,desc,{move,ability,source:O});

/* Story, Flyable Manor, ending-choice and overlooked early Act2 cosmetic corrections. */
const LATE_OUTFITS=[["Lune — Skirt outfit","When Esquie learns to SWIM in Act 2, head to the island off the Continent COAST near CRIMSON FOREST (reachable by sea, no flight needed). Look for the Gestral merchant GERANJO on the island's reachable shore and buy Lune's Skirt outfit for 1,000 Chroma.",["act2","Collectibles · Continent · Esquie swimming"],["swim"]],["Maelle — Real Maelle outfit","At the beginning of ACT 3, after completing the MONOLITH finale and the ensuing camp story sequences, Maelle receives REAL MAELLE as a story-unlocked outfit. Check Maelle's Outfit menu before starting your optional Continent sweep.",null,["fly"]],["Maelle — Civilian outfit","As soon as Esquie unlocks SWIMMING in Act 2, sail to the small island near CRIMSON FOREST and find Gestral merchant GERANJO beside the island's accessible beach. Buy Maelle's Civilian outfit for 1,000 Chroma.",["act2","Collectibles · Continent · Esquie swimming"],["swim"]],["Maelle — Painted Me outfit","In Act 3 reach THE CANVAS optional area and pick up the FAMILY PORTRAIT painting. Return to the MANOR through any accessible door, go to the ENTRANCE HALL stairway, and place the portrait in the EMPTY FRAME on the RIGHT wall of the MAIN STAIRCASE. Enter the newly opened ATELIER room and collect Maelle's Painted Me outfit.",null,["fly"]],["Monoco — Pure outfit","With Esquie's FLIGHT in Act 3, fly to the isolated shoreline at the SOUTHWEST edge of the Continent near the large LAKE and THE MEADOWS portal. Find merchant LUCAROPARFÉ on the coast and buy Monoco's Pure outfit for 10,000 Chroma.",null,["fly"]],["Maelle — Baguette outfit","After Esquie learns FLIGHT, enter THE REACHER and fast-travel to the LADDER AREA Expedition Flag. Investigate the side route beside the large LADDER to locate the hidden MIME and defeat it for Maelle's Baguette outfit.",null,["fly"]],["Monoco — Civilian outfit","Enter the flight-only ENDLESS NIGHT SANCTUARY in Act 3 and reach NIGHT TOTEM Expedition Flag. Find the Gestral merchant ANTHONYPO close to the totem; purchase Monoco's Civilian outfit for 10,000 Chroma.",null,["fly"]],["Monoco — Lumiere outfit","In Act 3 fly to FLYING CASINO and approach the BOARDED ENTRANCE to its casino building. Select MONOCO as the exploring character and repeatedly speak to the GESTRAL at the DOOR; insist through the conversation until he awards Monoco's Lumière outfit.",null,["fly"]],["Gustave — Civilian outfit","FINALE-CHOICE REWARD: Defeat the ACT 3 final boss and choose MAELLE'S 'A LIFE TO PAINT' ending. The game awards Gustave's Civilian outfit even though Gustave is unavailable in the post-Act 1 party; equip it in NG+. The opposite ending awards a different set, so collect that choice in another ending/playthrough if needed.",null,["fly"]],["Gustave — Renoir outfit","FINALE-CHOICE REWARD: At the ACT 3 final decision select VERSO'S ending ('A LIFE TO LOVE'). Complete its conclusion to receive Gustave's Renoir outfit. The competing MAELLE choice awards Civilian outfits instead; this cosmetic can be used when Gustave becomes playable on NG+.",null,["fly"]],["Lune — Civilian outfit","ACT 3 FINALE REWARD: Complete the final Lumière confrontation and choose MAELLE'S 'A LIFE TO PAINT' ending to unlock Lune's Civilian outfit. To collect outfits from Verso's alternative ending, use an earlier pre-finale save if available or another playthrough.",null,["fly"]],["Sciel — Civilian outfit","ACT 3 FINALE REWARD: After the final Lumière boss select MAELLE'S 'A LIFE TO PAINT' ending. This grants Sciel's Civilian outfit automatically; the reward cannot be bought at a merchant or found on the Continent.",null,["fly"]],["Verso — Renoir outfit","ACT 3 FINALE REWARD: After the last Lumière confrontation, choose VERSO'S 'A LIFE TO LOVE' ending rather than Maelle's. This grants Verso's Renoir outfit automatically as an ending reward.",null,["fly"]],["Lune — Clea outfit","In Act 3 FLY to FLYING MANOR and clear the route through CENTRAL PLAZA to the CLEA superboss. Defeat Clea, then return to the YOUNG BOY near the plaza and choose LUNE when he offers a gift. In newer versions this is a choice; the other two Clea outfits may require another NG+ run or a previously saved state.",["endgame","Collectibles · Flying Manor"],["fly"]],["Maelle — Clea outfit","In the flight-only FLYING MANOR clear CENTRAL PLAZA, defeat the boss CLEA and return to the YOUNG BOY near the plaza. When asked which character should receive the gift choose MAELLE to unlock Maelle's Clea outfit. Other recipients may require another playthrough.",["endgame","Collectibles · Flying Manor"],["fly"]],["Sciel — Clea outfit","In FLYING MANOR defeat the CLEA superboss and return to the YOUNG BOY near the CENTRAL PLAZA. Select SCIEL as the gift recipient to obtain Sciel's Clea outfit. In current versions do not assume the boy can award all three rewards in one run.",["endgame","Collectibles · Flying Manor"],["fly"]],["Verso — Clair outfit","At the flight-accessible ENDLESS TOWER complete the full challenge ladder through TRIAL 11, STAGE 3, not merely entering the tower. Claim Verso's Clair outfit from the final trial rewards.",["endgame","Collectibles · Endless Tower"],["fly"]],["Alicia","In FALLING LEAVES fast-travel to RESINVEIL GROVE Flag, walk RIGHT from the flag and descend the series of ROPES to the enormous cavern housing the LADY OF SAP. Enter the MANOR DOOR to the LEFT of her and pick up the ALICIA MUSIC RECORD from the TABLE in that room.",["act2","Collectibles · Falling Leaves"],["swim","reef"]],["Clea","Fly to the ENDLESS TOWER in Act 3 and complete ALL 33 TRIALS through the final STAGE 11 challenge. Claim the CLEA music record when the complete tower rewards are granted; it is not a pickup in Flying Manor.",["endgame","Collectibles · Endless Tower"],["fly"]],["Clea! Don't Pull Your Sister's Hair!","Once MONOCO'S STATION is open, enter FROZEN HEARTS from its EAST Continent exit and advance to GLACIAL FALLS Flag. From the flag take the RIGHT-HAND CAVE path (rather than walking toward the enemies), descend into the LARGE CAVERN and find the MANOR DOOR among its crystals. Inside the MANOR MUSIC ROOM pick up the Clea! Don't Pull Your Sister's Hair! record from the SINK/TABLE area.",["act2","Collectibles · Frozen Hearts"],["swim"]]];
for(const [name,desc,move,ability] of LATE_OUTFITS)apply(name,desc,{move,ability,source:O});
for(const name of ["Alicia","Clea","Clea! Don't Pull Your Sister's Hair!"]){
 const ids=(index.get(name)||[]).map(x=>x.entry[3]);
 ids.forEach(id=>audit.sources[id]="https://www.powerpyx.com/clair-obscur-expedition-33-all-record-locations/");
}

/* All base and update cosmetic records now have actionable acquisition instructions. */
const UPDATE_OUTFITS=[["Gustave — Osquio outfit","Enter VERSO'S DRAFTS after Esquie's diving quest, advance through GESTRAL BATHS, CANDY LAND and the GINGERBREAD DOOR to ROOT OF ALL EVIL. Defeat OSQUIO, the region's final boss. Gustave's Osquio outfit is one of its rewards; the outfit can be carried into NG+ for Gustave.",["update","Collectibles · Root of All Evil"],["dive"]],["Verso — Esquie outfit","In VERSO'S DRAFTS progress to CANDY LAND and the GESTRAL CAROUSEL section. Find the VERY VERY COOL GESTRAL near the CLIFF EDGE, speak to him with VERSO selected as your exploration character and complete the SWING/CAROUSEL RIDE to unlock Verso's Esquie outfit.",["update","Collectibles · Gestral Carousel"],["dive"]],["Verso — Osquio outfit","After entering VERSO'S DRAFTS via Esquie's dive ability, follow the main route through the GINGERBREAD DOOR to ROOT OF ALL EVIL. Defeat OSQUIO at the END of that zone to unlock Verso's Osquio outfit.",["update","Collectibles · Root of All Evil"],["dive"]],["Monoco — Esquie outfit","Inside VERSO'S DRAFTS use CANDY LAND Flag and reach GESTRAL CAROUSEL. Approach the VERY VERY COOL GESTRAL at the LEDGE near the carousel, select MONOCO as active explorer and complete the ride to claim Monoco's Esquie outfit.",["update","Collectibles · Gestral Carousel"],["dive"]],["Verso — Visages outfit","At ENDLESS TOWER after the CLEA boss encounter, follow the STAIRCASE beyond Clea, then walk UNDER THE STAIRS near the VISAGES PAINTING. Pick up Verso's Visages outfit hidden beneath the stairway; no separate Verso's Drafts boss is needed.",["update","Bonus Endless Tower"],["fly"]],["Monoco — Baguette outfit","In VERSO'S DRAFTS fast-travel to CANDY LAND Flag and take the LEFT HANDHOLD path toward its side courtyard. Find the unusually tough MIME in the area and defeat it to unlock Monoco's Baguette outfit and Baguettaro weapon.",["update","Collectibles · Candy Land"],["dive"]],["Gustave — Esquie outfit","Enter VERSO'S DRAFTS GESTRAL CAROUSEL, find the VERY VERY COOL GESTRAL beside the LEDGE and select VERSO to complete the SWING RIDE. Gustave's Esquie outfit is awarded as an extra reward for performing the ride AS VERSO. Gustave can wear it on NG+.",["update","Collectibles · Gestral Carousel"],["dive"]],["Lune — Esquie outfit","At VERSO'S DRAFTS GESTRAL CAROUSEL talk to the VERY VERY COOL GESTRAL near the LEDGE, select LUNE as your active character and complete his SWING RIDE to unlock Lune's Esquie outfit.",["update","Collectibles · Gestral Carousel"],["dive"]],["Maelle — Esquie outfit","At VERSO'S DRAFTS GESTRAL CAROUSEL travel toward the ledge beside the CAROUSEL, select MAELLE as the exploring character and accept the VERY VERY COOL GESTRAL'S ride challenge to receive Maelle's Esquie outfit.",["update","Collectibles · Gestral Carousel"],["dive"]],["Sciel — Esquie outfit","From VERSO'S DRAFTS CANDY LAND Flag move to the GESTRAL CAROUSEL area and find the VERY VERY COOL GESTRAL by its LEDGE. Select SCIEL as the exploration character before completing his ride to unlock Sciel's Esquie outfit.",["update","Collectibles · Gestral Carousel"],["dive"]],["Lune — Osquio outfit","Inside VERSO'S DRAFTS clear the GINGERBREAD DOOR progression to reach ROOT OF ALL EVIL. At MAIN FIELD Flag locate the GESTRAL MERCHANT in the Root zone and purchase Lune's Osquio outfit for 20,000 Chroma.",["update","Collectibles · Root of All Evil"],["dive"]],["Maelle — Osquio outfit","In ROOT OF ALL EVIL beyond the GINGERBREAD DOOR within VERSO'S DRAFTS, locate the Gestral merchant near MAIN FIELD Flag. Buy Maelle's Osquio outfit from him for 20,000 Chroma.",["update","Collectibles · Root of All Evil"],["dive"]],["Sciel — Osquio outfit","From ROOT OF ALL EVIL MAIN FIELD Flag find the GESTRAL MERCHANT selling the Osquio-themed clothing, and purchase Sciel's Osquio outfit for 20,000 Chroma.",["update","Collectibles · Root of All Evil"],["dive"]],["Monoco — Osquio outfit","In VERSO'S DRAFTS reach ROOT OF ALL EVIL beyond the GINGERBREAD DOOR. Find its GESTRAL MERCHANT near MAIN FIELD Flag and purchase Monoco's Osquio outfit for 20,000 Chroma.",["update","Collectibles · Root of All Evil"],["dive"]]];
for(const [name,desc,move,ability] of UPDATE_OUTFITS)apply(name,desc,{move,ability,source:O});

/* Chronological preflight: do not display any coral-reef pickup before Old Lumière. */
const act2Ch=chapters.find(c=>c.id==="act2");
if(act2Ch){
  const g=act2Ch.areas.find(a=>a[0]==="Collectibles · Coastal Cave"&&a[1].length);
  const after=act2Ch.areas.findIndex(a=>a[0]==="Continent · western expansion");
  if(g&&after>=0){
    act2Ch.areas.splice(act2Ch.areas.indexOf(g),1);
    const insertAfter=act2Ch.areas.findIndex(a=>a[0]==="Continent · western expansion");
    act2Ch.areas.splice(insertAfter+1,0,g);
    // All entrances to the eastern Coastal Cave shore require Old Lumière's reef crossing.
    for(const e of g[1]){
      const requirements=new Set(audit.requirements[e[3]]||[]);
      requirements.add("swim");requirements.add("reef");
      audit.requirements[e[3]]=[...requirements];
    }
  }
}

