const endingReqs=[
 ["Gustave — Civilian outfit","endingMaelle"],
 ["Lune — Civilian outfit","endingMaelle"],
 ["Sciel — Civilian outfit","endingMaelle"],
 ["Gustave — Renoir outfit","endingVerso"],
 ["Verso — Renoir outfit","endingVerso"]
];
